using System.Collections.ObjectModel;
using System.Diagnostics;
namespace VisionFramework;
public sealed class GraphExecutor(ModuleRegistry registry){
 static IReadOnlyDictionary<string,PortValue> Empty()=>new ReadOnlyDictionary<string,PortValue>(new Dictionary<string,PortValue>());
 public async Task<ExecutionSessionResult> RunAsync(ProcedureDocument procedure,string baseDirectory,IProgress<ExecutionEvent>? progress=null,CancellationToken cancellationToken=default,IReadOnlyDictionary<string,PortValue>? inputs=null,Func<NodeDocument,IReadOnlyDictionary<string,PortValue>,CancellationToken,Task<ExecutionSessionResult>>? callProcedure=null,ModuleExecutionScope? scope=null,ModuleRunControl? control=null,ResourceCatalog? resources=null){
  using var scopeLease=scope?.Enter();
  var initial=GraphValidator.Validate(procedure,registry);if(!initial.IsValid)throw new InvalidDataException(string.Join("; ",initial.Issues.Select(i=>i.Code+": "+i.Message)));
 var p=procedure with{Nodes=procedure.Nodes.Select(n=>n with{Call=n.Call?.Snapshot(),Parameters=n.Parameters.ToDictionary(x=>x.Key,x=>x.Value.Clone()),Rois=n.Rois?.Select(r=>r with{Vertices=r.Vertices is null?null:Array.AsReadOnly(r.Vertices.ToArray())}).ToArray()}).ToArray(),Connections=procedure.Connections.ToArray(),ExecutionLinks=procedure.ExecutionLinks?.ToArray(),Configuration=procedure.Configuration.Snapshot()};
 var validation=GraphValidator.Validate(p,registry);if(!validation.IsValid)throw new InvalidDataException(string.Join("; ",validation.Issues.Select(i=>i.Code+": "+i.Message)));
 var suppressed=new HashSet<string>();
 var calls=new Dictionary<string,ExecutionSessionResult>();var records=new Dictionary<string,NodeRunRecord>();var workflow=new WorkflowRunContext(p,inputs,records);void Report(string id,NodeRunStatus s,string? m=null){try{progress?.Report(new(id,s,m));}catch{}}
 foreach(var id in validation.ExecutionOrder){var n=p.Nodes.First(x=>x.Id==id);var sw=Stopwatch.StartNew();void Record(NodeRunStatus s,IReadOnlyDictionary<string,PortValue>? outputs=null,string? code=null,string? message=null,uint? nativeCode=null){records[id]=new(id,s,outputs??Empty(),sw.Elapsed.TotalMilliseconds,code,message){NativeErrorCode=nativeCode};workflow.Update(id);Report(id,s,message);}
 if(!n.Enabled){Record(NodeRunStatus.Skipped,message:"Disabled");continue;}if(cancellationToken.IsCancellationRequested){Record(NodeRunStatus.Cancelled,code:"Cancelled");continue;}
 if(ProcedureGraph.ExecutionEdges(p).Where(e=>e.ToNode==id).Any(e=>suppressed.Contains(e.FromNode)||records[e.FromNode].Status is not(NodeRunStatus.Success or NodeRunStatus.NoMatch))){Record(NodeRunStatus.Skipped,code:"ExecutionPredecessorUnavailable");continue;}
 var nodeInputs=new Dictionary<string,PortValue>();bool blocked=false;foreach(var c in p.Connections.Where(x=>x.ToNode==id)){var source=records[c.FromNode];if(source.Status is not(NodeRunStatus.Success or NodeRunStatus.NoMatch)||!source.Outputs.TryGetValue(c.FromPort,out var v)){blocked=true;break;}nodeInputs[c.ToPort]=v;}if(blocked){Record(NodeRunStatus.Skipped,code:"UpstreamUnavailable");continue;}
 var d=registry.GetDescriptor(n);var parameters=n.Parameters.ToDictionary(x=>x.Key,x=>x.Value);foreach(var spec in d.Parameters)if(!parameters.ContainsKey(spec.Name)&&spec.DefaultValue is {} def)parameters[spec.Name]=def.Clone();
 try{foreach(var binding in p.Configuration.Subscriptions.Where(b=>b.NodeId==id)){var value=workflow.Resolve(binding.Source);if(binding.IsParameter)parameters[binding.Target]=WorkflowSubscriptions.Parameter(d.Parameters.Single(p=>p.Name==binding.Target),value);else nodeInputs[binding.Target]=value;}}catch(Exception ex)when(ex is InvalidDataException or OverflowException){Record(NodeRunStatus.Failed,code:"SubscriptionUnavailable",message:ex.Message);continue;}
 foreach(var input in nodeInputs){var port=d.Inputs.FirstOrDefault(x=>x.Name==input.Key);if(port is not null&&!DataKinds.CanFlow(input.Value.Kind,port.Kind)){blocked=true;break;}}if(blocked){Record(NodeRunStatus.Failed,code:"InputTypeMismatch");continue;}
 IModule? module=null;ModuleResult? result=null;Exception? error=null;using var timeout=new CancellationTokenSource();if(n.TimeoutMs>0)timeout.CancelAfter(n.TimeoutMs);using var linked=CancellationTokenSource.CreateLinkedTokenSource(timeout.Token,cancellationToken,scope?.Stopping??CancellationToken.None);Report(id,NodeRunStatus.Running);
 try{if(n.ModuleId==WorkflowCalls.ModuleId){if(callProcedure is null)throw new InvalidOperationException("Subprogram requires solution execution context.");var child=await callProcedure(n,new ReadOnlyDictionary<string,PortValue>(nodeInputs),linked.Token);calls[id]=child;result=new(child.Status==SessionStatus.Success?ModuleStatus.Success:ModuleStatus.Failed,child.Status==SessionStatus.Success?child.WorkflowOutputs:Empty(),child.Status==SessionStatus.Success?null:"SubprogramFailed",child.Status==SessionStatus.Success?null:child.Status+": "+string.Join("; ",child.OutputErrors.Concat(child.Nodes.Where(r=>r.ErrorCode is not null).Select(r=>r.NodeId+": "+r.ErrorCode+" "+r.Message))));}else{module=registry.Create(n.ModuleId,n.ModuleVersion);result=await module.ExecuteAsync(new(id,Path.GetFullPath(baseDirectory),new ReadOnlyDictionary<string,PortValue>(nodeInputs),new ReadOnlyDictionary<string,System.Text.Json.JsonElement>(parameters),n.Rois){Scope=scope,Control=control,ProcedureId=p.Id,Resources=resources},linked.Token);}}catch(Exception ex){error=ex;}finally{try{if(module is IAsyncDisposable a)await a.DisposeAsync();else if(module is IDisposable b)b.Dispose();}catch(Exception ex){error??=ex;}}
 if(cancellationToken.IsCancellationRequested){Record(NodeRunStatus.Cancelled,code:"Cancelled");continue;}if(timeout.IsCancellationRequested){Record(NodeRunStatus.TimedOut,code:"Timeout",message:"Cooperative module timeout");continue;}if(error is not null){Record(NodeRunStatus.Failed,code:"ModuleException",message:error.Message);continue;}if(result is null){Record(NodeRunStatus.Failed,code:"InvalidResult");continue;}if((!Enum.IsDefined(result.Status)||!Enum.IsDefined(result.Continuation))){Record(NodeRunStatus.Failed,code:"InvalidResult",message:"Unknown module status");continue;}if(result.Status==ModuleStatus.Failed){var failureProblem=Outputs(d,result,false);Record(NodeRunStatus.Failed,failureProblem is null?new ReadOnlyDictionary<string,PortValue>(result.Outputs.ToDictionary(x=>x.Key,x=>x.Value)):null,code:failureProblem is null?result.ErrorCode??"ModuleFailed":"InvalidOutput",message:failureProblem??result.Message,nativeCode:result.NativeErrorCode);continue;}
 if(result.Continuation==ModuleContinuation.SuppressSuccessors)suppressed.Add(id);var problem=Outputs(d,result,result.Continuation==ModuleContinuation.Continue);if(problem is not null){Record(NodeRunStatus.Failed,code:"InvalidOutput",message:problem);continue;}Record(result.Status==ModuleStatus.NoMatch?NodeRunStatus.NoMatch:NodeRunStatus.Success,new ReadOnlyDictionary<string,PortValue>(result.Outputs.ToDictionary(x=>x.Key,x=>x.Value)),result.ErrorCode,result.Message,result.NativeErrorCode);
 }
 var all=validation.ExecutionOrder.Select(id=>records[id]).ToArray();var status=all.Any(n=>n.Status==NodeRunStatus.Cancelled)?SessionStatus.Cancelled:all.Any(n=>n.Status==NodeRunStatus.TimedOut)?SessionStatus.TimedOut:all.Any(n=>n.Status==NodeRunStatus.Failed)?SessionStatus.Failed:SessionStatus.Success;return workflow.Complete(new(status,Array.AsReadOnly(all)){Calls=new ReadOnlyDictionary<string,ExecutionSessionResult>(calls)});}
 static string? Outputs(ModuleDescriptor d,ModuleResult r,bool requireAll=true){if(r.Outputs is null)return "Null outputs";foreach(var pair in r.Outputs){var port=d.Outputs.FirstOrDefault(x=>x.Name==pair.Key);if(port is null)return "Unknown output: "+pair.Key;if(pair.Value is null||!DataKinds.CanFlow(pair.Value.Kind,port.Kind))return "Type mismatch: "+pair.Key;}foreach(var port in d.Outputs.Where(x=>requireAll&&x.Required))if(!r.Outputs.ContainsKey(port.Name))return "Missing output: "+port.Name;return null;}
}



